def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    # Attempt to convert a Point-like object into a JSON-serialisable dictionary.
    # Accept objects with 'x' and 'y' attributes, or two-element tuples/lists.
    if hasattr(value, "x") and hasattr(value, "y"):
        return {"x": value.x, "y": value.y}
    if isinstance(value, (list, tuple)) and len(value) == 2:
        return {"x": value[0], "y": value[1]}
    raise TypeError(f"Unsupported type {type(value)!r} for dehydrate_point")

