def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # assume the record stores the column names in ``self._keys`` and
    # the corresponding values in ``self._values``.  These names are
    # employed for both indexed and keyed access.
    if not hasattr(self, "_keys") or not hasattr(self, "_values"):
        # Fall back to a generic dict attribute if available.
        data = getattr(self, "data", "{}")
        if isinstance(data, dict):
            return dict(data) if not keys else {k: data.get(k, None) for k in keys}
        raise AttributeError("Record must provide _keys and _values attributes")

    if not keys:
        # return a full copy
        return dict(zip(self._keys, self._values))

    result = {}
    for k in keys:
        if isinstance(k, int):
            # indexed access
            if k < 0 or k >= len(self._values):
                raise IndexError(f"Index {k} out of range for record with {len(self._values)} items")
            key_name = self._keys[k]
            result[key_name] = self._values[k]
        else:
            # key access
            if k in self._keys:
                idx = self._keys.index(k)
                result[k] = self._values[idx]
            else:
                result[k] = None
    return result

