def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    class_attrs = {}

    # Initialize each field to None by default
    for field in fields:
        class_attrs[field] = None

    # Store the SRID mapping as a class attribute
    class_attrs['_srid_map'] = srid_map

    # Custom __init__ that accepts positional or keyword arguments
    def __init__(self, *args, **kwargs):
        for i, field in enumerate(fields):
            if i < len(args):
                setattr(self, field, args[i])
            else:
                setattr(self, field, kwargs.get(field))
        # Handle SRID conversion if provided
        srid_val = kwargs.get('srid')
        if srid_val is not None:
            mapped = srid_map.get(srid_val, srid_val)
            setattr(self, 'srid', mapped)
        else:
            # If no SRID passed, remove attribute if it existed
            if hasattr(self, 'srid'):
                delattr(self, 'srid')

    class_attrs['__init__'] = __init__

    # Provide a readable representation
    def __repr__(self):
        field_vals = ', '.join(f"{f}={getattr(self, f)!r}" for f in fields)
        return f"{name}({field_vals})"

    class_attrs['__repr__'] = __repr__

    # Create and return the new subclass of Point
    return type(name, (Point,), class_attrs)

