def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    import traceback, os

    def _short_path(path):
        parts = path.split(os.sep)
        return os.sep.join(parts[-max_path_level:]) if len(parts) > max_path_level else path

    lines = []
    exc_type = type(e).__name__
    try:
        exc_msg = str(e)
    except Exception:
        exc_msg = "<unable to convert exception to string>"
    lines.append(f"{exc_type}: {exc_msg}")

    tb = e.__traceback__
    if tb:
        stack = traceback.extract_tb(tb)
        if len(stack) > max_level:
            stack = stack[-max_level:]
        for i, frame in enumerate(reversed(stack), 1):
            file_path = _short_path(frame.filename)
            lines.append(f"  {i} {file_path}:{frame.lineno} in {frame.name}")
            if frame.line:
                lines.append(f"    {frame.line.strip()}")

    for attr in ("__cause__", "__context__"):
        inner = getattr(e, attr, None)
        if inner and not (attr == "__context__" and getattr(e, "__suppress_context__", False)):
            if attr == "__cause__":
                lines.append("Caused by:")
            else:
                lines.append("During handling of the above exception, another exception occurred:")
            lines.extend(cls.extostr(inner, max_level, max_path_level).splitlines())

    return "\n".join(lines)

