def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface."""
    # Collect the attribute-name → description mapping.
    # Individual element classes should define an ``ATTRIBUTES`` dict
    # mapping each attribute name to its description.
    # If ``all`` is ``True`` we walk the MRO to include attributes
    # from base classes as well.
    result = {}
    if all:
        # Combine attributes from all classes in the MRO, giving
        # precedence to subclasses (hence reverse order).
        for cls in reversed(self.__class__.mro()):
            attrs = getattr(cls, "ATTRIBUTES", None)
            if isinstance(attrs, dict):
                for name, desc in attrs.items():
                    if name not in result:
                        result[name] = desc
    else:
        attrs = getattr(self.__class__, "ATTRIBUTES", None)
        if isinstance(attrs, dict):
            result.update(attrs)
    return result

