def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if all:
        attrs = set()
        # Include class (and base class) attributes that are not methods or private
        for cls in self.__class__.mro():
            for key, val in getattr(cls, "__dict__", {}).items():
                if key.startswith("_") or callable(val):
                    continue
                attrs.add(key)
        # Include instance attributes
        attrs.update({k for k in getattr(self, "__dict__", {}) if not k.startswith("_")})
        return sorted(attrs)
    else:
        # Return only the instance's own public attributes
        return [k for k in getattr(self, "__dict__", {}) if not k.startswith("_")]

