def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Build list of output lines
    lines = []

    if header is not None:
        lines.append(str(header))

    # Iterate over points in the graph.  The exact point interface is
    # not part of this snippet, but we try to be flexible: we look for
    # common attributes that hold coordinates and values.
    for point in self:
        # Get coordinates: prefer 'coords', then 'pos', then 'x' / 'y' etc.
        if hasattr(point, 'coords'):
            coords = point.coords
        elif hasattr(point, 'pos'):
            coords = point.pos
        elif hasattr(point, 'x') and hasattr(point, 'y'):
            coords = (getattr(point, 'x'), getattr(point, 'y'))
        else:
            # Fall back to string representation
            coords = getattr(point, 'value', point)

        if isinstance(coords, (list, tuple)):
            coord_str = separator.join(map(str, coords))
        else:
            coord_str = str(coords)

        # Get value(s): prefer 'value', then 'val', then maybe 'values'
        if hasattr(point, 'value'):
            values = point.value
        elif hasattr(point, 'val'):
            values = point.val
        elif hasattr(point, 'values'):
            values = point.values
        else:
            values = None

        if isinstance(values, (list, tuple)):
            val_str = separator.join(map(str, values))
        else:
            val_str = str(values)

        # Combine
        if val_str == '':
            line = coord_str
        else:
            line = coord_str + separator + val_str

        lines.append(line)

    return "\n".join(lines)

