def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # ``_err_indices`` is assumed to be a dictionary mapping coordinate
    # names (strings) to a list of indices where an error occurs.
    # This method performs a safe lookup and returns an empty list
    # if either the attribute or the key is missing.
    if not isinstance(coord_name, str):
