def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Treat Source instances separately to avoid treating them as a suitable sequence
    if isinstance(seq, Source):
        return False
    # Direct FillRequest instance satisfies the requirement
    if isinstance(seq, FillRequest):
        return True
    # Sequence-like objects (but not strings/bytes) are inspected for a FillRequest
    if isinstance(seq, (str, bytes)):
        return False
    try:
        for item in seq:
            if isinstance(item, FillRequest):
                return True
        return False
    except TypeError:
        # seq is not iterable
        return False

