def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.
    """
    errors = []

    for key, val in labels.items():
        # validate key
        if not isinstance(key, str):
            errors.append({repr(key): "expected string or bytes-like object"})
        else:
            if not LABEL_KEY_REGEX.match(key):
                errors.append(
                    {
                        key: f"Label key '{key}' does not match the regex "
                        f"{LABEL_KEY_REGEX.pattern}"
                    }
                )

        # validate value
        if isinstance(val, str):
            if not LABEL_VALUE_REGEX.match(val):
                errors.append(
                    {
                        key: f"Label value '{val}' does not match the regex "
                        f"{LABEL_VALUE_REGEX.pattern}"
                    }
                )
        elif isinstance(val, list):
            for item in val:
                if not isinstance(item, str):
                    errors.append({repr(item): "expected string or bytes-like object"})
                else:
                    if not LABEL_VALUE_REGEX.match(item):
                        errors.append(
                            {
                                item: f"Label value '{item}' does not match the regex "
                                f"{LABEL_VALUE_REGEX.pattern}"
                            }
                        )
        else:
            # non-string, non-list value error
            errors.append({key: "expected string or bytes-like object"})

    if errors:
        raise ValidationError(errors)

