def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Determine the specification version to use for validation
    spec_version = getattr(self, "spec_version", None)
    if extract_spec_version:
        # Try to extract the type/value from the inventory.  The inventory
        # may be a dict-like object or an object with attributes.
        inv_type = None
        if isinstance(inventory, dict):
            inv_type = inventory.get("type")
        else:
            inv_type = getattr(inventory, "type", None)

        # Map known types to specification versions
        if isinstance(inv_type, str):
            if inv_type.lower() in ("folia", "f-l-i-a"):
                spec_version = "1.4"  # example default
            elif inv_type.lower() in ("xml", "schema"):
                spec_version = "1.3"
            # If the type is not recognised, fall back to the instance's spec_version
        # If the inventory itself declares a spec_version, prefer that if not None
        if hasattr(inventory, "spec_version") and inventory.spec_version:
            spec_version = inventory.spec_version

    # Basic sanity checks – the inventory must expose an id, type and metadata
    # section.  Accept both dict-like and attribute-based interfaces.
    required_keys = {"id", "type", "metadata"}
    provided = set()
    if isinstance(inventory, dict):
        provided = set(inventory.keys())
    else:
        for key in required_keys:
            if hasattr(inventory, key):
                provided.add(key)

    missing = required_keys - provided
    if missing:
        raise ValueError(
            f"Inventory missing required key(s): {', '.join(sorted(missing))}"
        )

    # If the inventory contains its own spec_version field, check for consistency
    inv_spec_version = None
    if isinstance(inventory, dict):
        inv_spec_version = inventory.get("spec_version")
    else:
        inv_spec_version = getattr(inventory, "spec_version", None)

    if inv_spec_version and spec_version and inv_spec_version != spec_version:
        raise ValueError(
            f"Inventory spec_version '{inv_spec_version}' "
            f"does not match expected '{spec_version}'."
        )

    # Validate the metadata section – at least title and author are required
    metadata = None
    if isinstance(inventory, dict):
        metadata = inventory["metadata"]
    else:
        metadata = getattr(inventory, "metadata", None)

    if not isinstance(metadata, (dict, object)):
        raise ValueError("Metadata must be a dict-like object or object with attributes.")

    # Check required metadata subfields
    for meta_key in ("title", "author"):
        exists = False
        if isinstance(metadata, dict):
            exists = meta_key in metadata
        else:
            exists = hasattr(metadata, meta_key)
        if not exists:
            raise ValueError(f"Metadata missing required field '{meta_key}'.")

    # If all checks pass, return True; otherwise an exception will have been raised
    return True

