def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Initialize the mapping
    path_map = {}

    # Get all versions to consider: the given version and any later versions
    # (assuming version comparison is valid; adjust as needed for your version type)
    versions_to_consider = [v for v in inventory.keys() if v >= version]
    versions_to_consider.sort()

    for v in versions_to_consider:
        state = inventory.get(v, {})
        if not isinstance(state, dict):
            # If for some reason the state entry is not a dict, skip it
            continue
        for logic_path, files in state.items():
            # Ensure we treat files as a set
            if isinstance(files, (list, set, tuple)):
                file_set = set(files)
            else:
                file_set = {files}
            if logic_path in path_map:
