def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def wrapper(localtime):
        name = namefunc(localtime)
        try:
            # In Python 2, unicode objects need to be encoded to bytes
            if isinstance(name, unicode):  # noqa: F821
                return name.encode('utf-8')
        except NameError:
            # In Python 3, `unicode` is not defined – no conversion needed
            pass
        return name
    return wrapper

