def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        tuple: (num_objects, good_objects) where
            num_objects is the total number of objects checked
            good_objects is the number of objects that passed validation
    """
    if hasattr(self, "walk"):
        # Assume walk yields all descendant objects, including self
        iterator = self.walk()
    else:
        # Fallback: iterate over container directly
        iterator = iter(self)

    num_objects = 0
    good_objects = 0

    for obj in iterator:
        # Skip the root if it's self/this object, it might not have validate()
        if obj is self:
            continue

        # Do we have a validate method? If not, skip unless we wish to warn
        if hasattr(obj, "validate"):
            num_objects += 1
            if validate_objects:
                try:
                    # The validate method is expected to return True/False
                    # or raise an exception on failure
                    valid = obj.validate(check_digests=check_digests)
                except Exception as exc:
                    if show_warnings:
                        print(f"[WARNING] Exception while validating {obj!r}: {exc}")
                    continue
                if valid:
                    good_objects += 1
                else:
                    if show_warnings:
                        print(f"[WARNING] Validation failed for {obj!r}")
            else:
                # Count but do not validate
                num_objects += 0
        else:
            if show_warnings:
                print(f"[WARNING] Object {obj!r} has no validate() method and was skipped")
    return num_objects, good_objects}

