def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import xml.etree.ElementTree as ET

    def load_inventory(path):
        """Return a dict mapping file paths to digest values from an inventory XML."""
        inv = {}
        try:
            tree = ET.parse(path)
            root = tree.getroot()
            for doc in root.findall('.//document'):
                fpath = doc.get('path')
                digest = doc.get('digest')
                if fpath and digest:
                    inv[fpath] = digest
        except Exception:
            pass
        return inv

    root_inventory = None
    missing = []
    differing = {}
    for idx, dir_name in enumerate(version_dirs):
        inv_path = os.path.join(dir_name, 'inventory.xml')
        if not os.path.isfile(inv_path):
            missing.append(dir_name)
            continue
        inv = load_inventory(inv_path)
        if idx == 0:
            root_inventory = inv
        else:
            for fp, digest in inv.items():
                root_digest = root_inventory.get(fp)
                if root_digest and root_digest != digest:
                    differing.setdefault(fp, []).append([dir_name, digest])

    if missing:
        raise ValueError(f"Missing inventory files in: {', '.join(missing)}")

    # Store the differing digests for later validation checks
    self.different_digests = differing
    return True

