def bash_completion():
    '''
    Return a bash completion script for the borgmatic command.
    Produce this by introspecting borgmatic's command-line argument parsers.
    '''
    import importlib
    try:
        cli_module = importlib.import_module('borgmatic.cli')
    except Exception as e:
        return f'# Could not import borgmatic.cli: {e}\n'
    main_cmd = getattr(cli_module, 'cli', None)
    if main_cmd is None:
        return '# borgmatic.cli.cli not found\n'
    # Try Click's built‑in Bash completion
    try:
        import click
        from click import shell_completion
        if hasattr(shell_completion, 'get_completion_script'):
            return shell_completion.get_completion_script(main_cmd, name='borgmatic', shell='bash')
    except Exception:
        pass
    # Fallback: Use argparse introspection if the CLI is an argparse parser
    try:
        import argparse
        if isinstance(main_cmd, argparse.ArgumentParser):
            opts = [
                action.option_strings[0]
                for action in main_cmd._actions
                if action.option_strings
            ]
            subcmds = []
            for action in main_cmd._actions:
                if isinstance(action, argparse._SubParsersAction):
                    subcmds = list(action.choices.keys())
                    break
            all_words = opts + subcmds
            script = (
                ' _borgmatic_complete() {\n'
                '    local cur words\n'
                '    _init_completion -n = || return\n'
                '    COMPREPLY=( $(compgen -W \'\n'
                f"            {' '.join(all_words)}\n"
                "            \' -- \"$cur\") )\n"
                ' }\n'
                ' complete -F _borgmatic_complete borgmatic\n'
            )
            return script
    except Exception:
        pass
    return '# Unable to generate bash completion script for borgmatic.\n'

