def _resolve_string(matcher):
    """Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Determine whether matcher has named groups or positional groups
    if hasattr(matcher, "groupdict"):
        name = matcher.groupdict().get("name")
        default = matcher.groupdict().get("default")
    else:
        # Fallback to positional groups
        name = matcher.group(1) if matcher.lastindex >= 1 else None
        default = matcher.group(2) if matcher.lastindex >= 2 else None

    if name is None:
        raise ValueError("Matcher does not contain a variable name.")

    env_value = os.getenv(name)
    if env_value is None:
        if default is None:
            raise ValueError(
                f"Environment variable '{name}' is not set and no default value provided"
            )
        return default.strip()
    return env_value

