def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*.

    Parameters:
        iface: The interface or base class that *candidate* should provide.
        candidate: The class or instance to be verified.
        tentative (bool): If True, the function will return ``False`` instead of
                          raising an exception when the candidate does not
                          satisfy the interface.

    Returns:
        bool: ``True`` if *candidate* satisfies *iface*, otherwise ``False``
              (or an exception if ``tentative`` is ``False``).
    """
    # First check for the common case where both iface and candidate are
    # classes (including ABCs). In that situation a simple ``issubclass``
    # suffices.
    if isinstance(candidate, type) and isinstance(iface, type):
        ok = issubclass(candidate, iface)
    else:
        # For duck-typing we fall back to checking that all public attributes
        # of the interface exist on the candidate.
        try:
            # If the interface is a typing.Protocol or has __abstractmethods__,
            # use those as the required attributes.
            if hasattr(iface, "__abstractmethods__"):
                required = set(iface.__abstractmethods__)
            else:
                required = {
                    name
                    for name in dir(iface)
                    if not name.startswith("_")
                    and callable(getattr(iface, name, None))
                }
        except Exception:
            # In case iface is not a class-like object, consider all
            # attributes that the candidate actually has.
            required = set(dir(iface)) if not isinstance(iface, type) else set()

        ok = all(hasattr(candidate, attr) for attr in required)

    if not ok:
        if tentative:
            return False
        raise TypeError(f"Candidate {candidate!r} does not provide interface {iface}")

    return True

