def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # If an explicit metaclass is supplied, it wins.
    if explicit_mc is not None:
        return explicit_mc

    # Gather the metaclasses of all non-None bases.
    metaclasses = set(type(b) for b in bases if b is not None)

    # If there are no bases or all bases have no custom metaclass, default to `type`.
    if not metaclasses:
        return type
    if len(metaclasses) == 1:
        return metaclasses.pop()

    # If multiple metaclasses are present, try to find one that
    # is a subclass of all others. This is the "most-derived" metaclass.
    chosen = None
    for candidate in metaclasses:
        if all(issubclass(candidate, others) for others in metaclasses):
            if chosen is not None and chosen is not candidate:
                # Ambiguous: more than one suitable candidate.
                break
            chosen = candidate

    if chosen is None:
        raise TypeError(
            "metaclass conflict: metaclass conflict among bases: "
            + ", ".join(m.__name__ for m in sorted(metaclasses, key=lambda c: c.__name__))
        )

    return chosen

