def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re

    # Find all code block spans (```) to ignore tags inside them
    code_blocks = []
    for m in re.finditer(r'```.*?```', text, flags=re.S):
        code_blocks.append((m.start(), m.end()))

    tag_pattern = re.compile(r'\B#(?P<tag>\w+)\b')

    tags = set()

    def _replace(match):
        pos = match.start()
        # Skip replacement if inside a code block
        for start, end in code_blocks:
            if start <= pos < end:
                return match.group(0)
        tag = match.group('tag')
        tags.add(tag)
        if replacer:
            return replacer(tag)
        return match.group(0)

    replaced_text = tag_pattern.sub(_replace, text)

    return tags, replaced_text

