def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try JSON first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            return data
    except Exception:
        pass  # Not JSON, fall back to XRD parsing

    # XRD parsing
    try:
        root = ET.fromstring(document)
    except ET.ParseError as e:
        raise ValueError("Cannot parse webfinger document as JSON or XRD") from e

    def local(tag):
        return tag.split('}', 1)[-1] if '}' in tag else tag

    result: Dict[str, object] = {}

    # Extract <Subject>
    for child in root:
        if local(child.tag) == 'Subject':
            result['subject'] = child.text
            break

    # Extract <Link> elements
    links = []
    for link in root.findall('.//*'):
        if local(link.tag) == 'Link':
            attrs = {}
            for attr in ['rel', 'type', 'href', 'template', 'name', 'profile']:
                if link.get(attr) is not None:
                    attrs[attr] = link.get(attr)
            if attrs:
                links.append(attrs)

    if links:
        result['links'] = links

    return result

