def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document.
    Does not raise if it fails.
    """
    try:
        if '@' not in handle:
            return None
        user, domain = handle.split('@', 1)
        url = f"https://{domain}/.well-known/webfinger?resource=acct:{user}@{domain}"
        req = urllib.request.Request(url,
                                     headers={'User-Agent': 'Python Webfinger Client'})
        with urllib.request.urlopen(req, timeout=10) as resp:
            data = resp.read()
            if not data:
                return None
            return data.decode('utf-8')
    except Exception:
        return None

