def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file, either a dict or a YAML string
    :raise IRValidatorException: when mandatory data is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("No spec content provided")

    # If the content is a string, assume YAML and load it
    if isinstance(spec_content, str):
        try:
            # import yaml lazily to avoid mandatory dependency if unused
            import yaml
            spec_data = yaml.safe_load(spec_content)
        except Exception as exc:
            raise IRValidatorException(f"Failed to parse YAML spec content: {exc}") from exc
    elif isinstance(spec_content, dict):
        spec_data = spec_content
    else:
        raise IRValidatorException(
            f"Unsupported spec_content type: {type(spec_content).__name__}"
        )

    # Determine the required fields for validation
    required_fields = getattr(cls, "REQUIRED_FIELDS", [])
    if required_fields is None:
        required_fields = []

    # Validate each required field exists
    missing = [field for field in required_fields if field not in spec_data]
    if missing:
        missing_str = ", ".join(missing)
        raise IRValidatorException(
            f"Missing required field(s) in spec file: {missing_str}"
        )

    return spec_data

