def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    # Helper to recursively resolve include directives in a nested dictionary.
    def _resolve(item):
        if isinstance(item, dict):
            if "include" in item:
                # Resolve included spec file or dictionary.
                # It is up to the concrete implementation to provide
                # `self._load_spec(path)` which returns the parsed dictionary.
                inc_path = item["include"]
                included = self._load_spec(inc_path) if hasattr(self, "_load_spec") else {}
                # Merge included dict into current, with current keys overwriting.
                merged = {**included, **{k: v for k, v in item.items() if k != "include"}}
                return _resolve(merged)
            else:
                return {k: _resolve(v) for k, v in item.items()}
        elif isinstance(item, list):
            return [_resolve(v) for v in item]
        else:
            return item

    return _resolve(parser_dict)

