    """Check if all the required arguments have been provided. """
    required = getattr(self, "REQUIRED_ATTRIBS", None)
    if not required:
        return
    # Build a set of names that are already present on self
    existing = set()
    for attr in required:
        if getattr(self, attr, None) is not None:
            existing.add(attr)
    # Combine with keys passed in args
    supplied = set(args or {})
    missing = [a for a in required if a not in supplied and a not in existing]
    if missing:
