def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    min_val = getattr(self, 'minimum', None)
    max_val = getattr(self, 'maximum', None)

    # If no bounds are defined, nothing to check
    if min_val is None and max_val is None:
        return

    for val in args:
        if val is None:
            continue
        if min_val is not None and val < min_val:
            raise ValueError(
                f"Argument value {val} is less than the minimum allowed {min_val}."
            )
        if max_val is not None and val > max_val:
            raise ValueError(
                f"Argument value {val} exceeds the maximum allowed {max_val}."
            )

