def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
       """
        # Attempt to use a predefined mapping of argument types if available
        arg_type_map = getattr(self, "_arg_type_map", {}).get(parser_name, {})
        for key, val in list(values_dict.items()):
            if val is None:
                continue
            # Use explicit type mapping if defined
            if key in arg_type_map:
                target_type = arg_type_map[key]
                try:
                    values_dict[key] = target_type(val)
                except Exception:
                    # Fall back to string if conversion fails
                    values_dict[key] = val
                continue

            # Generic conversion: try bool, int, float in order
            lower = str(val).lower()
            if lower in ("true", "false"):
                values_dict[key] = lower == "true"
            else:
                try:
                    values_dict[key] = int(val)
                except (ValueError, TypeError):
                    try:
                        values_dict[key] = float(val)
                    except (ValueError, TypeError):
                        # Leave as original string
                        values_dict[key] = val

